script:
(function () {
  'use strict';
  // Withdrawals from a governmental 457(b) after leaving the job.
  //   Each year, at the start of the year: withdrawal = planned amount (rising by the yearly increase),
  //     or the required minimum distribution if larger (from the RMD age: prior year-end balance /
  //     Uniform Lifetime Table entry), or whatever is left. The rest grows at the expected return.
  //   Federal tax on the withdrawal = tax(other income + withdrawal) - tax(other income), with the
  //     standard deduction, the extra 65+ standard deduction and the 2025-2028 senior deduction
  //     (6% phase-out on income above $75,000 / $150,000 joint). Brackets and deductions rise each year
  //     by the yearly increase (a stand-in for IRS inflation indexing); the senior phase-out threshold is
  //     fixed by law. State tax = flat rate x withdrawal.
  //   No 10% additional tax: IRC 72(t) does not apply to governmental 457(b) distributions (it applies
  //     only to amounts rolled in from an IRA, 401(k) or 403(b), IRC 72(t)(9)).
  //   Withdrawal that lasts to a chosen age: B / sum ((1 + g) / (1 + r))^k, k = 0..n-1 (growing
  //     annuity-due, before RMDs).
  // Checked in Node (scratch tests, whole script with a fake DOM):
  //   Single, $20,000 other income + $30,000 withdrawal in 2026: taxable $33,900, tax $3,820 vs $390
  //     on $20,000 alone -> $3,430 federal on the withdrawal; top bracket 12%.
  //   MFJ, both 66, $40,000 + $30,000: deductions $32,200 + 2 x $1,650 + 2 x $6,000 = $47,500 -> taxable
  //     $22,500, tax $2,250; on $40,000 alone taxable $0 -> $2,250 on the withdrawal.
  //   Senior phase-out: single 70, $100,000 total income -> senior deduction 6,000 - 6% x 25,000 = $4,500.
  //   $400,000, $30,000 a year flat, 5% return: balance hits zero during the 21st year (annuity-due:
  //     n = -ln(1 - 400,000 x 0.05 / (30,000 x 1.05)) / ln 1.05 = 20.6 years).
  //   Withdrawal lasting 41 years (55 to 95) at 5% with 2.5% increases = $400,000 / 26.363 = $15,173.
  //   Senior deduction stops after 2028: single 70, $100,000 -> deductions $22,650 in 2026, $18,150 in 2029.
  //   RMD start ages 72/73/73/75 for births 1950/1951/1959/1960; RMD at 75 (born 1960 or later) on $300,000 = $300,000 / 24.6 = $12,195.12.
  // ---- 2026 FEDERAL CONSTANTS (tax year 2026) -------------------------------------------
  // Brackets and standard deductions: IRS Rev. Proc. 2025-32 (as amended by P.L. 119-21); same values
  //   as income-tax-calculator and take-home-paycheck-calculator.
  // Additional standard deduction (65+) and senior deduction ($6,000 per person 65+, tax years
  //   2025-2028): IRC 63(f) and 151(d)(5)(C) as amended by P.L. 119-21; Rev. Proc. 2025-32.
  // RMD start age: IRC 401(a)(9)(C) as amended by SECURE 2.0 (72 if born 1950 or earlier, 73 if born
  //   1951-1959, 75 if born 1960 or later). Uniform Lifetime Table: Treas. Reg. 1.401(a)(9)-9(c) =
  //   Pub. 590-B Table III (same values as rmd-calculator and 72t-calculator).
  var TAX_YEAR = 2026;
  var BRACKETS = { // upper limit of each band; rates 10, 12, 22, 24, 32, 35, 37%
    single: [12400, 50400, 105700, 201775, 256225, 640600],
    mfj:    [24800, 100800, 211400, 403550, 512450, 768700],
    hoh:    [17700, 67450, 105700, 201750, 256200, 640600]
  };
  var RATES = [0.10, 0.12, 0.22, 0.24, 0.32, 0.35, 0.37];
  var STANDARD_DEDUCTION = { single: 16100, mfj: 32200, hoh: 24150 };
  var ADDITIONAL_65 = { single: 2050, hoh: 2050, mfj: 1650 };          // per person 65+
  var SENIOR_DEDUCTION = 6000, SENIOR_LAST_YEAR = 2028, SENIOR_RATE = 0.06;
  var SENIOR_START = { single: 75000, hoh: 75000, mfj: 150000 };        // not inflation-indexed
  var UNIFORM = { 72: 27.4, 73: 26.5, 74: 25.5, 75: 24.6, 76: 23.7, 77: 22.9, 78: 22.0, 79: 21.1, 80: 20.2,
    81: 19.4, 82: 18.5, 83: 17.7, 84: 16.8, 85: 16.0, 86: 15.2, 87: 14.4, 88: 13.7, 89: 12.9, 90: 12.2, 91: 11.5,
    92: 10.8, 93: 10.1, 94: 9.5, 95: 8.9, 96: 8.4, 97: 7.8, 98: 7.3, 99: 6.8, 100: 6.4, 101: 6.0, 102: 5.6, 103: 5.2,
    104: 4.9, 105: 4.6, 106: 4.3, 107: 4.1, 108: 3.9, 109: 3.7, 110: 3.5, 111: 3.4, 112: 3.3, 113: 3.1, 114: 3.0,
    115: 2.9, 116: 2.8, 117: 2.7, 118: 2.5, 119: 2.3, 120: 2.0 };
  var EARLY_PENALTY = 0.10, MAX_AGE = 110;
  // ----------------------------------------------------------------------------------------------

  function rmdAge(birthYear) { return birthYear <= 1950 ? 72 : birthYear <= 1959 ? 73 : 75; }

  // Federal income tax for one year. f = inflation factor since 2026, seniors = people 65+.
  function federalTax(income, status, f, seniors, year) {
    var deduction = (STANDARD_DEDUCTION[status] + seniors * ADDITIONAL_65[status]) * f;
    if (year <= SENIOR_LAST_YEAR && seniors > 0) {
      deduction += seniors * Math.max(0, SENIOR_DEDUCTION - SENIOR_RATE * Math.max(0, income - SENIOR_START[status]));
    }
    var taxable = Math.max(0, income - deduction), tax = 0, lower = 0, top = 0;
    for (var i = 0; i < RATES.length; i++) {
      var upper = i < BRACKETS[status].length ? BRACKETS[status][i] * f : Infinity;
      if (taxable > lower) { tax += (Math.min(taxable, upper) - lower) * RATES[i]; top = RATES[i]; }
      lower = upper;
    }
    return { tax: tax, taxable: taxable, top: taxable > 0 ? top : 0 };
  }

  // p: balance, age, spouseAge, withdraw, rate, inflation, other, state (decimals), status
  function project(p) {
    var bal = p.balance, rows = [], total = 0, totalTax = 0, early = 0, rmdFrom = NaN, lastAge = NaN, depleted = false;
    var startRmd = rmdAge(TAX_YEAR - p.age);
    for (var y = 0; p.age + y <= MAX_AGE && bal > 0.005; y++) {
      var a = p.age + y, f = Math.pow(1 + p.inflation, y), planned = p.withdraw * f;
      var rmd = a >= startRmd && UNIFORM[Math.min(a, 120)] ? bal / UNIFORM[Math.min(a, 120)] : 0;
      if (rmd > planned + 0.005 && isNaN(rmdFrom)) rmdFrom = a;
      var w = Math.min(bal, Math.max(planned, rmd));
      var seniors = (a >= 65 ? 1 : 0) + (p.status === 'mfj' && p.spouseAge + y >= 65 ? 1 : 0);
      var other = p.other * f;
      var withTax = federalTax(other + w, p.status, f, seniors, TAX_YEAR + y);
      var fed = withTax.tax - federalTax(other, p.status, f, seniors, TAX_YEAR + y).tax;
      var st = w * p.state;
      bal = (bal - w) * (1 + p.rate);
      if (bal < 0.005) { bal = 0; depleted = true; }
      if (a < 60) early += w;
      total += w; totalTax += fed + st; lastAge = a;
      rows.push({ year: TAX_YEAR + y, age: a, w: w, rmd: rmd > planned + 0.005, fed: fed, st: st, net: w - fed - st,
                  end: bal, top: withTax.top });
    }
    return { rows: rows, total: total, totalTax: totalTax, early: early, rmdFrom: rmdFrom, rmdAge: startRmd,
             lastAge: lastAge, depleted: depleted || bal <= 0.005 };
  }

  function sustainable(balance, n, r, g) {
    var s = 0;
    for (var k = 0; k < n; k++) s += Math.pow((1 + g) / (1 + r), k);
    return s > 0 ? balance / s : 0;
  }

  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  function fmt(x) { return money.format(Math.abs(x) < 0.5 ? 0 : x); }
  function pct(x) { return (Math.round(x * 1000) / 10) + '%'; }
  function num(id) { var v = parseFloat(document.getElementById(id).value); return isNaN(v) ? NaN : v; }
  function set(id, t) { document.getElementById(id).textContent = t; }

  function update() {
    var balance = num('pwBalance'), age = num('pwAge'), withdraw = num('pwWithdraw'), rate = num('pwRate'),
        inflation = num('pwInflation'), other = num('pwOther'), state = num('pwState'), spouseAge = num('pwSpouseAge'),
        planAge = num('pwPlanAge'), status = document.getElementById('pwFiling').value;
    var joint = status === 'mfj';
    document.getElementById('pwSpouseWrap').hidden = !joint;
    var error = document.getElementById('pwError');
    var bad = [balance, age, withdraw, rate, inflation, other, state, planAge].some(isNaN) ||
              age !== Math.round(age) || age < 18 || age > 100 || balance <= 0 || withdraw < 0 || other < 0 ||
              rate < -20 || rate > 30 || inflation < 0 || inflation > 15 || state < 0 || state > 15 ||
              planAge !== Math.round(planAge) || planAge < age || planAge > MAX_AGE ||
              (joint && (isNaN(spouseAge) || spouseAge !== Math.round(spouseAge) || spouseAge < 18 || spouseAge > 110));
    error.hidden = !bad;
    if (bad) {
      error.textContent = 'Enter a balance above $0, a whole-number age from 18 to 100, non-negative amounts, a return from -20 to 30%, ' +
                          'a yearly increase up to 15%, a state rate up to 15% and a “last to” age from your age to ' + MAX_AGE + '.';
      return;
    }
    var p = { balance: balance, age: age, spouseAge: joint ? spouseAge : 0, withdraw: withdraw, rate: rate / 100,
              inflation: inflation / 100, other: other, state: state / 100, status: status };
    var r = project(p);
    var first = r.rows[0];
    set('pwLasts', !r.depleted ? 'Past age ' + MAX_AGE : 'Age ' + r.lastAge);
    set('pwNet', fmt(first.net));
    set('pwNetMonthly', fmt(first.net / 12) + ' a month');
    set('pwFed', fmt(first.fed));
    set('pwStateTax', fmt(first.st));
    set('pwEff', first.w > 0 ? pct((first.fed + first.st) / first.w) : '–');
    set('pwBracket', first.top > 0 ? pct(first.top) : '0% (covered by deductions)');
    set('pwPenalty', '$0 – governmental 457(b)');
    set('pwSustain', fmt(sustainable(balance, planAge - age + 1, rate / 100, inflation / 100)) + ' a year, rising ' + inflation + '% a year');
    set('pwTotal', fmt(r.total));
    set('pwTotalTax', fmt(r.totalTax));
    var earlyEl = document.getElementById('pwEarly');
    earlyEl.hidden = !(r.early > 0);
    if (r.early > 0) {
      set('pwEarly', 'You take ' + fmt(r.early) + ' before 59½ with no 10% additional tax, because a governmental 457(b) ' +
          'is exempt once you leave the employer. From a traditional IRA the same withdrawals would cost ' + fmt(r.early * EARLY_PENALTY) +
          ' more. Money you rolled into the 457(b) from an IRA, 401(k) or 403(b) still carries the 10% rule.');
    }
    var rmdEl = document.getElementById('pwRmdNote');
    rmdEl.hidden = isNaN(r.rmdFrom);
    if (!isNaN(r.rmdFrom)) {
      set('pwRmdNote', 'Required minimum distributions start at ' + r.rmdAge + ' for you. From age ' + r.rmdFrom +
          ' the RMD is larger than your planned withdrawal, so the schedule takes the RMD.');
    }
    var body = document.getElementById('pwSchedule');
    body.textContent = '';
    r.rows.forEach(function (row) {
      var tr = document.createElement('tr');
      [row.year, row.age, fmt(row.w) + (row.rmd ? ' (RMD)' : ''), fmt(row.fed), fmt(row.st), fmt(row.net), fmt(row.end)].forEach(function (v) {
        var td = document.createElement('td'); td.textContent = v; tr.appendChild(td);
      });
      body.appendChild(tr);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('pwForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
